function countDomesticTradeCountersThisTurn(state, responderId, proposerId) {
  if (proposerId === null) {
    return 0;
  }
  return state.domesticTradeCountersThisTurn.filter(
    (counter) => counter.responderId === responderId && counter.proposerId === proposerId
  ).length;
}

