// bot/src/difficulty.ts
var DIFFICULTY_KEYS = ["easy", "normal", "hard"];
var isDifficultyKey = createKeyGuard(DIFFICULTY_KEYS);
var DIFFICULTY_PRESETS = Object.freeze({
  // Easy: a beginner should be able to win — frequent suboptimal moves.
  easy: Object.freeze({
    blunderProbability: 0.3,
    turnLookaheadSecondPlyK: 0,
    turnLookaheadCandidateLimit: 70
  }),
  // Normal (default): strongest validated policy, with no deliberate mistakes.
  normal: Object.freeze({ blunderProbability: 0 }),
  // Hard: zero decision noise, and NO validated strength premium over Normal.
  //
  // MEASURED 2026-08-09, humans base, 150 seeds x 3 rotations (450 games, 0
  // timeouts): easy 21.11% / normal 40.00% / hard 38.89%. normal - easy is
  // +18.89pp (z=5.48, p<1e-4); hard - normal is -1.11pp (z=-0.31, p=0.76).
  // A deeper/wider second ply (secondPlyK 3, candidateLimit 200 — values that
  // strictly exceed the humans overlay's own K 2 / limit 140) was run in that
  // same measurement and bought nothing, at ~43% more candidate budget per
  // decision. Not shipped.
  //
  // The trap this replaced: hard previously declared K 2 / discount 0.55 /
  // limit 140 — exactly what the humans preset already sets. Difficulty
  // composes last, but every human-facing seat is forced onto the humans
  // profile first, so that premium resolved BIT-IDENTICAL to Normal at the only
  // tables a human plays on. Any future premium here must strictly exceed the
  // humans overlay or it is a silent no-op; tests/bot/difficulty-distinct.test.ts
  // fails on an equal-valued one.
  //
  // blunderProbability is the only lever with a demonstrated gradient, and it
  // only points one way (weaker). Making Hard genuinely harder needs a
  // mechanism that does not yet exist — not a bigger search budget.
  //
  // personality-resolved arming state.
  hard: Object.freeze({ blunderProbability: 0 })
});
validateTuningPresetRegistry("difficulty", DIFFICULTY_PRESETS);
function tuningForDifficulty(difficulty, base = DEFAULT_TUNING) {
  const key = isDifficultyKey(difficulty) ? difficulty : "normal";
  return mergeTuningOverrides(DIFFICULTY_PRESETS[key], base);
}

